-- [DB GEÇMİŞİNDEN KURTARILDI 2026-07-11] Bu migration canlı veritabanına uygulanmıştı ancak repoda dosyası yoktu; supabase_migrations.schema_migrations.statements kolonundan geri çıkarıldı.

CREATE TABLE IF NOT EXISTS public.texts (key TEXT PRIMARY KEY, value TEXT NOT NULL DEFAULT '', category TEXT DEFAULT 'ui', updated_at TIMESTAMPTZ DEFAULT NOW() NOT NULL, updated_by UUID REFERENCES auth.users(id) ON DELETE SET NULL);
ALTER TABLE public.texts ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS texts_public_read ON public.texts;
CREATE POLICY texts_public_read ON public.texts FOR SELECT USING (true);
DROP POLICY IF EXISTS texts_admin_write ON public.texts;
CREATE POLICY texts_admin_write ON public.texts FOR ALL USING (public.is_platform_admin()) WITH CHECK (public.is_platform_admin());
INSERT INTO public.texts (key, value, category) VALUES ('dashboardTitle','ANA SAYFA','ui'),('dashboardSubtitle','OYNA''YA HOŞ GELDİN','ui'),('communityViewTitle','TOPLULUKLAR','ui'),('profileTitle','OYUNCU PROFİLİ','ui'),('matchDiscoveryTitle','MAÇ BUL','ui'),('marketplaceGkTitle','KALECİ KİRALA','ui'),('marketplaceRefTitle','HAKEM KİRALA','ui'),('pitchDiscoveryTitle','SAHA KİRALA','ui'),('opponentFinderTitle','RAKİP BUL','ui'),('studioTitle','TAKTİK ZEKA','ui') ON CONFLICT (key) DO NOTHING;
CREATE TABLE IF NOT EXISTS public.promo_codes (id UUID DEFAULT gen_random_uuid() PRIMARY KEY, code TEXT NOT NULL UNIQUE, description TEXT, discount_type TEXT NOT NULL DEFAULT 'PERCENT' CHECK (discount_type IN ('PERCENT','FIXED')), discount_value NUMERIC NOT NULL CHECK (discount_value > 0), max_redemptions INTEGER, redemption_count INTEGER DEFAULT 0, valid_from TIMESTAMPTZ DEFAULT NOW(), valid_until TIMESTAMPTZ, target_segment TEXT DEFAULT 'ALL' CHECK (target_segment IN ('ALL','PRO','CAPTAIN','OWNER','NEW_USERS')), is_active BOOLEAN DEFAULT true, created_by UUID REFERENCES auth.users(id) ON DELETE SET NULL, created_at TIMESTAMPTZ DEFAULT NOW() NOT NULL);
CREATE TABLE IF NOT EXISTS public.promo_redemptions (id UUID DEFAULT gen_random_uuid() PRIMARY KEY, promo_id UUID NOT NULL REFERENCES public.promo_codes(id) ON DELETE CASCADE, user_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, redeemed_at TIMESTAMPTZ DEFAULT NOW() NOT NULL, UNIQUE(promo_id, user_id));
ALTER TABLE public.promo_codes ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.promo_redemptions ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS promo_codes_admin ON public.promo_codes;
CREATE POLICY promo_codes_admin ON public.promo_codes FOR ALL USING (public.is_platform_admin()) WITH CHECK (public.is_platform_admin());
DROP POLICY IF EXISTS promo_codes_public_read ON public.promo_codes;
CREATE POLICY promo_codes_public_read ON public.promo_codes FOR SELECT USING (is_active = true AND (valid_until IS NULL OR valid_until > NOW()));
DROP POLICY IF EXISTS promo_redemptions_own ON public.promo_redemptions;
CREATE POLICY promo_redemptions_own ON public.promo_redemptions FOR SELECT USING (user_id = auth.uid() OR public.is_platform_admin());
DROP POLICY IF EXISTS promo_redemptions_insert_own ON public.promo_redemptions;
CREATE POLICY promo_redemptions_insert_own ON public.promo_redemptions FOR INSERT WITH CHECK (user_id = auth.uid());
CREATE TABLE IF NOT EXISTS public.owner_billing_events (id UUID DEFAULT gen_random_uuid() PRIMARY KEY, owner_user_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, event_type TEXT NOT NULL, amount NUMERIC, currency TEXT DEFAULT 'TRY', external_id TEXT, payload JSONB DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ DEFAULT NOW() NOT NULL);
CREATE INDEX IF NOT EXISTS idx_owner_billing_events_owner ON public.owner_billing_events(owner_user_id);
ALTER TABLE public.owner_billing_events ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS owner_billing_events_admin ON public.owner_billing_events;
CREATE POLICY owner_billing_events_admin ON public.owner_billing_events FOR ALL USING (public.is_platform_admin()) WITH CHECK (public.is_platform_admin());
DROP POLICY IF EXISTS owner_billing_events_owner_read ON public.owner_billing_events;
CREATE POLICY owner_billing_events_owner_read ON public.owner_billing_events FOR SELECT USING (owner_user_id = auth.uid());
CREATE TABLE IF NOT EXISTS public.admin_team_members (id UUID DEFAULT gen_random_uuid() PRIMARY KEY, user_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE UNIQUE, admin_role TEXT NOT NULL DEFAULT 'ADMIN' CHECK (admin_role IN ('SUPER_ADMIN','ADMIN','MODERATOR','FINANCE','SUPPORT')), permissions JSONB DEFAULT '[]'::jsonb, invited_by UUID REFERENCES auth.users(id) ON DELETE SET NULL, created_at TIMESTAMPTZ DEFAULT NOW() NOT NULL);
ALTER TABLE public.admin_team_members ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS admin_team_platform_admin ON public.admin_team_members;
CREATE POLICY admin_team_platform_admin ON public.admin_team_members FOR ALL USING (public.is_platform_admin()) WITH CHECK (public.is_platform_admin());
ALTER TABLE public.wallet_transactions ADD COLUMN IF NOT EXISTS match_id UUID;
DROP POLICY IF EXISTS "Platform admins read wallet ledger" ON public.wallet_transactions;
CREATE POLICY "Platform admins read wallet ledger" ON public.wallet_transactions FOR SELECT USING (public.is_platform_admin());
DROP POLICY IF EXISTS "Admins manage disputes" ON public.match_disputes;
CREATE POLICY "Admins manage disputes" ON public.match_disputes FOR ALL USING (public.is_platform_admin()) WITH CHECK (public.is_platform_admin());
DROP POLICY IF EXISTS "Platform admins read booking payments" ON public.booking_payments;
CREATE POLICY "Platform admins read booking payments" ON public.booking_payments FOR SELECT USING (public.is_platform_admin());
